#include "support/session_image_peer.h"
static void mifCrc(unsigned char* B,size_t N)
{uint32 C=xrtCrc32(B,N-4);for(unsigned I=0;I<4;++I)B[N-1-I]=(unsigned char)(C>>(I*8));}
static xmqttsessionstatus mifRestore(xmqttsessionconfig* K,xmqttsessionimageconfig* C,const unsigned char* B,size_t N)
{xmqttsession* S=(xmqttsession*)(uintptr_t)1;xmqttsessionstatus R=xmqttSessionImageRestore(K,C,(xbytesview){B,N},&S);testRequire((R==XMQTT_SESSION_DONE||R==XMQTT_SESSION_RESET)?S!=(xmqttsession*)(uintptr_t)1:S==(xmqttsession*)(uintptr_t)1,"restore output atomicity");if(R==XMQTT_SESSION_DONE||R==XMQTT_SESSION_RESET)miStop(S,C->MonotonicTime);xrtClearError();return R;}
static void mifCorruption(void)
{
    xmqttsession* S=miPopulate(XMQTT_VERSION_5,false);xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);xmqttsessionimageconfig C=miConfig(11,1000000);unsigned char B[4096],X[4096];size_t N=miWrite(S,&C,B,sizeof(B));testRequire(N==188,"literal version1 MQTT5 fixture layout");miStop(S,12);C=miConfig(5,1001500);
    for(size_t I=0;I<N;++I){miStatus(mifRestore(&K,&C,B,I),XMQTT_SESSION_PROTOCOL_ERROR,"every truncated image fails atomically");memcpy(X,B,N);X[I]^=1;miStatus(mifRestore(&K,&C,X,N),XMQTT_SESSION_PROTOCOL_ERROR,"every one-bit corruption fails CRC");}
    memcpy(X,B,N);X[N]=0;miStatus(mifRestore(&K,&C,X,N+1),XMQTT_SESSION_PROTOCOL_ERROR,"no accepted trailing/coalesced image");
    const unsigned Offsets[]={7,8,10,12,13,14,16,48,52,56,58,62,79,80,82,83};
    for(unsigned I=0;I<sizeof(Offsets)/sizeof(*Offsets);++I){memcpy(X,B,N);X[Offsets[I]]=0xff;mifCrc(X,N);xmqttsessionstatus R=mifRestore(&K,&C,X,N);testRequire(R<0||R==XMQTT_SESSION_LIMIT,"CRC-valid malformed format/metadata rejected");}
    const unsigned SemanticOffsets[]={60,91,106,140,182,87};
    for(unsigned I=0;I<sizeof(SemanticOffsets)/sizeof(*SemanticOffsets);++I){memcpy(X,B,N);unsigned At=SemanticOffsets[I];if(At==60){X[60]=X[61]=0;}else if(At==91)X[91]|=8u;else if(At==106){X[106]=X[107]=0;}else if(At==140)X[140]=7;else if(At==182)X[182]=17;else X[90]=1;mifCrc(X,N);miStatus(mifRestore(&K,&C,X,N),XMQTT_SESSION_PROTOCOL_ERROR,"literal CRC-valid zero/duplicate id, DUP or property count mismatch");}
    C.WallMilliseconds=999999;miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_STATE_ERROR,"backward wall time fails closed");C.WallMilliseconds=1001500;C.Binding=XRT_BYTES_LITERAL("b\0q");miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_STATE_ERROR,"same ClientId cannot retarget broker binding");C.Binding=XRT_BYTES_LITERAL("b\0p");K.ClientId=XRT_STR_LITERAL("other-client");miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_STATE_ERROR,"ClientId binding required");K=miSessionConfig(XMQTT_VERSION_311);miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_STATE_ERROR,"MQTT version binding required");K=miSessionConfig(XMQTT_VERSION_5);
    /* Semantic damage after valid CRC: duplicate outgoing id and forbidden
     * alias/flags/state metadata must not be accepted as an expired empty image. */
    memcpy(X,B,N);X[80]=2;mifCrc(X,N);C.WallMilliseconds=1060000;miStatus(mifRestore(&K,&C,X,N),XMQTT_SESSION_PROTOCOL_ERROR,"expired image still rejects inconsistent attempt/sent flags");
    uint32 Seed=0x8934abcdu;C.WallMilliseconds=1001500;for(unsigned I=0;I<10000;++I){memcpy(X,B,N);Seed=Seed*1664525u+1013904223u;size_t At=Seed%(N-4);Seed=Seed*1664525u+1013904223u;X[At]^=(unsigned char)(1u<<(Seed%8));mifCrc(X,N);xmqttsession* R=(xmqttsession*)(uintptr_t)1;xmqttsessionstatus Status=xmqttSessionImageRestore(&K,&C,(xbytesview){X,N},&R);
        if(Status==XMQTT_SESSION_DONE||Status==XMQTT_SESSION_RESET){xmqttsessioninfo Info=miInfo(R);testRequire(!Info.Connected&&Info.Objects<=K.MaxOutgoing&&Info.Incoming<=K.MaxIncoming&&Info.LiveBytes<=K.MaxBytes,"accepted mutation preserves bounded state");unsigned char Again[4096];size_t M=miWrite(R,&C,Again,sizeof(Again));miStatus(mifRestore(&K,&C,Again,M),XMQTT_SESSION_DONE,"accepted mutation has valid normalized image");miStop(R,C.MonotonicTime);}
        else {testRequire(R==(xmqttsession*)(uintptr_t)1,"fuzz failure changed output");}xrtClearError();}
}
static void mifLimitsAndAliases(void)
{
    xmqttsession* S=miPopulate(XMQTT_VERSION_5,false);xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);xmqttsessionimageconfig C=miConfig(11,1000000);unsigned char B[4096],X[4096],Old[4096];size_t N=miWrite(S,&C,B,sizeof(B));memset(X,0xa5,sizeof(X));memcpy(Old,X,sizeof(X));size_t Out=123;
    for(size_t I=0;I<N;++I){miStatus(xmqttSessionImageWrite(S,&C,X,I,&Out),XMQTT_SESSION_LIMIT,"every short write atomic");testRequire(Out==123&&!memcmp(X,Old,sizeof(X)),"short write changed buffer/size");}
    C.MaxBytes=N-1;miStatus(xmqttSessionImageSize(S,&C,&Out),XMQTT_SESSION_LIMIT,"image cap bounds Size");testRequire(Out==123,"image cap changed measured output");miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_LIMIT,"image cap bounds restore before allocation");C.MaxBytes=sizeof(B);
    miStatus(xmqttSessionImageWrite(S,&C,X,sizeof(X),(size_t*)X),XMQTT_SESSION_ERROR,"write output aliases buffer");testRequire(!memcmp(X,Old,sizeof(X)),"alias refusal changed buffer");xrtClearError();miStatus(xmqttSessionImageSize(S,&C,(size_t*)S),XMQTT_SESSION_ERROR,"size cannot overwrite Session");xrtClearError();miStatus(xmqttSessionImageWrite(S,&C,(ptr)S,16,&Out),XMQTT_SESSION_ERROR,"write cannot overwrite Session");xrtClearError();
    miStatus(xmqttSessionImageSize(S,&C,(size_t*)&C),XMQTT_SESSION_ERROR,"size cannot overwrite config");xrtClearError();C.MonotonicTime=9;miStatus(xmqttSessionImageSize(S,&C,&Out),XMQTT_SESSION_STATE_ERROR,"snapshot cannot precede protocol time");xrtClearError();C.MonotonicTime=NAN;miStatus(xmqttSessionImageSize(S,&C,&Out),XMQTT_SESSION_ERROR,"nonfinite clock rejected");xrtClearError();C=miConfig(11,1000000);C.Binding=(xbytesview){NULL,1};miStatus(xmqttSessionImageSize(S,&C,&Out),XMQTT_SESSION_ERROR,"invalid binding rejected");xrtClearError();C=miConfig(11,1000000);
    xmqttsession* Sentinel=(xmqttsession*)(uintptr_t)1;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},(xmqttsession**)B),XMQTT_SESSION_ERROR,"restore cannot overwrite its input");miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){(const unsigned char*)(uintptr_t)(UINTPTR_MAX-1),8},&Sentinel),XMQTT_SESSION_ERROR,"wrapped image range rejected");testRequire(Sentinel==(xmqttsession*)(uintptr_t)1,"invalid input changed output");xrtClearError();K.MaxOutgoing=2;miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_LIMIT,"restored outgoing cap");K=miSessionConfig(XMQTT_VERSION_5);K.MaxIncoming=1;miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_LIMIT,"restored incoming cap");K=miSessionConfig(XMQTT_VERSION_5);K.Codec.MaxPayloadBytes=2;miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_LIMIT,"restored codec payload cap");K=miSessionConfig(XMQTT_VERSION_5);xmqttsession* Base=miCreate(XMQTT_VERSION_5);K.MaxBytes=miInfo(Base).BaseBytes+1;miStop(Base,0);miStatus(mifRestore(&K,&C,B,N),XMQTT_SESSION_LIMIT,"restored aggregate byte cap");miStop(S,12);
}
static void mifBudgets(void)
{
    xmqttsession* S=miPopulate(XMQTT_VERSION_5,false);xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);xmqttsessionimageconfig C=miConfig(11,1000000);unsigned char B[4096];size_t N=miWrite(S,&C,B,sizeof(B));xrtSetErrorInfo(XERR_STATE,"image.ambient",1,"preserve");const xerror* Error=xrtGetError();xallocationbudget* Budget=NULL;xallocationscope Scope={0};testRequire(xrtAllocationBudgetCreate(1,&Budget)&&xrtAllocationBudgetEnter(Budget,&Scope),"image budget1 scope");
    for(unsigned I=0;I<10000;++I){size_t Size=0,Written=0;miStatus(xmqttSessionImageSize(S,&C,&Size),XMQTT_SESSION_DONE,"budget1 Size");miStatus(xmqttSessionImageWrite(S,&C,B,sizeof(B),&Written),XMQTT_SESSION_DONE,"budget1 Write");testRequire(Size==N&&Written==N&&xrtGetError()==Error,"successful image operation preserves allocation/error identity");}
    testRequire(xrtAllocationBudgetLeave(&Scope),"leave image budget1");xallocationbudgetinfo BI={.Size=sizeof(BI)};testRequire(xrtAllocationBudgetInfo(Budget,&BI)&&!BI.PeakBytes&&!BI.Rejections,"Size/Write perform no heap allocation");xrtAllocationBudgetFree(Budget);xrtClearError();miStop(S,12);
    C=miConfig(5,1001500);xmqttsession* Control=NULL;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},&Control),XMQTT_SESSION_DONE,"allocation-size control");xmqttsessioninfo ControlInfo=miInfo(Control);size_t Base=ControlInfo.BaseBytes,Packet=(ControlInfo.LiveBytes-Base)/3u;testRequire(Packet&&(ControlInfo.LiveBytes-Base)%3u==0,"three identical allocation-size packet controls");miStop(Control,C.MonotonicTime);
    const size_t Limits[]={1,128,8192,16384,24576,32768,65536,131072,Base-1,Base,Base+Packet-1,Base+Packet,Base+2*Packet-1,Base+2*Packet,Base+3*Packet-1,Base+3*Packet};unsigned Failed=0,Passed=0;
    for(unsigned I=0;I<sizeof(Limits)/sizeof(*Limits);++I){testRequire(xrtAllocationBudgetCreate(Limits[I],&Budget)&&xrtAllocationBudgetEnter(Budget,&Scope),"restore actual allocation budget");xmqttsession* R=(xmqttsession*)(uintptr_t)1;xmqttsessionstatus Status=xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},&R);
        if(Status==XMQTT_SESSION_DONE){++Passed;miStop(R,C.MonotonicTime);}else{++Failed;testRequire(Status==XMQTT_SESSION_ERROR&&R==(xmqttsession*)(uintptr_t)1,"OOM type/output atomicity");}xrtClearError();testRequire(xrtAllocationBudgetLeave(&Scope),"restore budget leave");BI=(xallocationbudgetinfo){.Size=sizeof(BI)};testRequire(xrtAllocationBudgetInfo(Budget,&BI)&&!BI.LiveBytes&&!BI.LiveCount,"all partial restore owners physically refunded");if(I>=8)testRequire(Status==(I==15?XMQTT_SESSION_DONE:XMQTT_SESSION_ERROR),"each constructor/packet allocation boundary actually injected");printf("[BUDGET] limit%zu status%d peak%zu rejections%llu live%zu\n",Limits[I],Status,BI.PeakBytes,(unsigned long long)BI.Rejections,BI.LiveBytes);xrtAllocationBudgetFree(Budget);}
    testRequire(Failed&&Passed,"actual failure and successful allocation controls");
    K.MaxBytes=0;testRequire(xrtAllocationBudgetCreate(1,&Budget)&&xrtAllocationBudgetEnter(Budget,&Scope),"fixed storage refusal before allocation");xmqttsession* Empty=(xmqttsession*)(uintptr_t)1;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},&Empty),XMQTT_SESSION_LIMIT,"fixed byte cap is typed LIMIT even with diagnostic OOM budget");testRequire(Empty==(xmqttsession*)(uintptr_t)1&&xrtAllocationBudgetLeave(&Scope),"fixed-cap output/scope");BI=(xallocationbudgetinfo){.Size=sizeof(BI)};testRequire(xrtAllocationBudgetInfo(Budget,&BI)&&!BI.PeakBytes&&!BI.Rejections,"fixed storage preflight performs no allocation");xrtAllocationBudgetFree(Budget);K=miSessionConfig(XMQTT_VERSION_5);
    B[N-1]^=1;testRequire(xrtAllocationBudgetCreate(1,&Budget)&&xrtAllocationBudgetEnter(Budget,&Scope),"malformed diagnostic OOM scope");xmqttsession* R=(xmqttsession*)(uintptr_t)1;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},&R),XMQTT_SESSION_PROTOCOL_ERROR,"diagnostic OOM cannot change malformed status");testRequire(R==(xmqttsession*)(uintptr_t)1,"diagnostic OOM output atomicity");xrtClearError();testRequire(xrtAllocationBudgetLeave(&Scope),"diagnostic OOM leave");BI=(xallocationbudgetinfo){.Size=sizeof(BI)};testRequire(xrtAllocationBudgetInfo(Budget,&BI)&&!BI.LiveBytes&&!BI.LiveCount,"diagnostic OOM has no owners");xrtAllocationBudgetFree(Budget);
}
int main(void){mifCorruption();mifLimitsAndAliases();mifBudgets();puts("[PASS] image truncation/corruption/CRC-valid mutations/bindings/limits/aliases/zero-heap/real OOM");return 0;}
